import 'package:flutter_timeago_pro/flutter_timeago_pro.dart';

final dt = DateTime.now().subtract(const Duration(minutes: 25));
print(dt.toTimeagoFormat()); // "25m ago"

final future = DateTime.now().add(const Duration(minutes: 45));
print(future.toTimeagoFormat()); // "in 45m"
